def as_str(value: bytes | str) -> str:
    """Return a string representation of *value*.

    If *value* is a ``bytes`` object it is decoded as UTF‑8, otherwise it is returned
    unchanged (assuming it is already a ``str``). This helper is useful when the
    code needs to accept either type without raising ``TypeError``.
    """
    if isinstance(value, bytes):
        return value.decode("utf-8")
    return value
